function qmImei() {
  try {
    var v = vars.get && vars.get('imei_ip');
    return String(v || '2937357107');
  } catch (e) {
    return '2937357107';
  }
}
const QM_BC = 'https://api-bc.wtzw.com';
const QM_KS = 'https://api-ks.wtzw.com';
const QM_KEY = 'd3dGiJc651gSQ8w1';
const QM_AES = '242ccb8230d709e1';
const QM_HEADER_BASE = {
  'app-version': '80400',
  platform: 'android',
  reg: '0',
  AUTHORIZATION: '',
  'application-id': 'com.****.reader',
  'net-env': '1',
  channel: 'unknown',
  'qm-params': ''
};

function qmSign(params) {
  const source = Object.keys(params).sort().map(k => k + '=' + params[k]).join('') + QM_KEY;
  return native.md5(source);
}

function qmHeaders() {
  const headers = {};
  Object.keys(QM_HEADER_BASE).forEach(key => {
    if (String(QM_HEADER_BASE[key]) !== '') headers[key] = QM_HEADER_BASE[key];
  });
  headers.sign = qmSign(headers);
  return headers;
}

function qmQs(params) {
  return Object.keys(params).map(k => k + '=' + encodeURIComponent(params[k])).join('&');
}

function qmApi(base, path, params) {
  const query = Object.assign({}, params, { sign: qmSign(params) });
  return base + path + '?' + qmQs(query);
}

function qmRequest(base, path, params) {
  const url = qmApi(base, path, params);
  const headers = qmHeaders();
  const res = http.get(url, { headers, timeout: 15000 });
  if (!res.ok) throw new Error('七猫接口请求失败：HTTP ' + res.status + (res.error ? ' ' + res.error : ''));
  const data = res.json();
  if (data.errors && data.errors.details) {
    throw new Error('七猫接口错误：' + data.errors.details + '（' + (data.errors.code || '未知') + '）');
  }
  return data;
}

function qmBookId(ctx) {
  const kept = ctx.book && ctx.book.vars ? String(ctx.book.vars.bookId || '') : '';
  if (kept) return kept;
  const url = String((ctx.book && ctx.book.bookUrl) || ctx.baseUrl || '');
  let m = url.match(/[?&](?:bookId|book_id|id)=([0-9]+)/);
  if (m) return m[1];
  m = url.match(/qm:\/\/([0-9]+)\//);
  if (m) return m[1];
  m = url.match(/page\/([0-9]+)/);
  return m ? m[1] : '';
}

function qmBookUrl(id) {
  const ip = qmImei();
  return 'https://api-bc.wtzw.com/api/v4/book/detail?id=' + encodeURIComponent(String(id)) +
    '&imei_ip=' + encodeURIComponent(ip) + '&teeny_mode=0';
}

function qmBookFields(book) {
  const words = Number(book.words_num || 0);
  const wordText = words >= 10000 ? (words / 10000).toFixed(1) + '万字' : (words ? String(words) + '字' : '');
  const tags = Array.isArray(book.book_tag_list)
    ? book.book_tag_list.map(x => String(x.title || '')).filter(Boolean).join(',')
    : '';
  const pub = String(book.type) === '2' || String(book.category_type) === 'publish' ? '出版' : '';
  const kind = [pub, book.category1_name, book.category2_name, tags].filter(Boolean).join(',');
  return {
    name: String(book.title || ''),
    author: String(book.author || ''),
    kind: kind,
    intro: String(book.intro || ''),
    coverUrl: String(book.image_link || '').replace(
      /_[0-9]+x[0-9]+(?=\.(?:jpe?g|png|webp)(?:[?#]|$))/i,
      '_360x480'
    ),
    wordCount: wordText,
    lastChapter: String(book.latest_chapter_title || ''),
    updateTime: book.update_time ? native.formatDate(Number(book.update_time) * 1000, 'yyyy-MM-dd HH:mm') : '',
    status: String(book.is_over) === '1' ? '完结' : '连载',
    type: 'text',
    bookUrl: qmBookUrl(book.id)
  };
}

function qmSearch(ctx) {
  const page = Number(ctx.page || 1);
  const data = qmRequest(QM_BC, '/search/v1/words', {
    gender: '3',
    imei_ip: qmImei(),
    page: String(page),
    wd: String(ctx.key || '')
  });
  const books = (data.data && data.data.books) || [];
  return books.map(qmBookFields);
}

function qmDetail(ctx) {
  const id = qmBookId(ctx);
  if (!id) throw new Error('缺少七猫书籍 ID');
  const data = qmRequest(QM_BC, '/api/v4/book/detail', {
    id: id,
    imei_ip: qmImei(),
    teeny_mode: '0'
  });
  const book = data.data && data.data.book;
  if (!book) throw new Error('七猫详情接口未返回书籍');
  if (String(book.id || '') !== id) throw new Error('七猫详情接口返回了不匹配的书籍');
  const fields = qmBookFields(book);
  fields.bookUrl = qmBookUrl(id);
  keep('bookId', id);
  return fields;
}

function qmToc(ctx) {
  const id = qmBookId(ctx);
  if (!id) throw new Error('缺少七猫书籍 ID，无法获取目录');
  const data = qmRequest(QM_KS, '/api/v1/chapter/chapter-list', { id: id });
  const reader = data.data || {};
  const agent = String(reader.reader_type) === '4' ? '1' : '0';
  const chapters = Array.isArray(reader.chapter_lists) ? reader.chapter_lists : [];
  return chapters.map(ch => ({
    title: String(ch.title || ''),
    // 末段带 content_md5：段评批量统计 /api/v1/paragraph/bubbles 必须用它
    url: 'qm://' + id + '/' + String(ch.id || '') + '/' + agent + '/' + String(ch.content_md5 || ''),
    tag: ch.words ? String(ch.words) + '字' : ''
  }));
}

function qmContent(ctx) {
  const url = String((ctx.chapter && ctx.chapter.url) || ctx.url || '');
  const m = url.match(/^qm:\/\/([0-9]+)\/([^/]+)\/([01])(?:\/([0-9a-f]*))?$/);
  if (!m) throw new Error('无法解析七猫章节地址：' + url);
  const params = { id: m[1], chapterId: m[2] };
  if (m[3] === '1') params.reader_agent = '1';
  const data = qmRequest(QM_KS, '/api/v1/chapter/content', params);
  if (!data.data || !data.data.content) throw new Error('七猫正文接口未返回内容');
  const raw = native.base64Bytes(data.data.content);
  const plain = native.decrypt('AES/CBC/PKCS5Padding', raw.slice(16), QM_AES, raw.slice(0, 16));
  return native.fromBytes(plain);
}
const QM_CHANNELS = { male: '1', female: '2', publish: '3' };

function qmChannelCode(value) {
  const text = String(value || '');
  if (text === 'female' || text === '女频') return 'female';
  if (text === 'publish' || text === '出版') return 'publish';
  return 'male';
}

function qmCategoryMenu(channel) {
  const tab = QM_CHANNELS[channel] || QM_CHANNELS.male;
  const data = qmRequest(QM_BC, '/api/v5/category/index', {
    gender: '0',
    category_id: '0',
    tab_type: tab,
    cache_ver: ''
  });
  const groups = Array.isArray(data.data && data.data.category_list) ? data.data.category_list : [];
  const links = [];
  groups.forEach(group => {
    const items = (Array.isArray(group.list) ? group.list : []).filter(x => x.category_id);
    if (!items.length) return;
    links.push({ title: '【' + String(group.title || group.show_title || '分类') + '】' });
    items.forEach(x => links.push({
      title: String(x.title || ''),
      url: channel + '|' + x.category_id + '|' + (x.category_type || '0')
    }));
  });
  return links;
}

function qmCatUrl(cid, ch, page) {
  var p = Number(page) || 1;
  var gmap = { male: "1", female: "2", publish: "3" };
  var gender = gmap[ch] || "1";
  var key = "d3dGiJc651gSQ8w1";
  var params = {
    category_id: String(cid), category_type: "2", gender: gender,
    book_preference: "1", read_preference: "0", from: "4", need_filters: "1",
