  };
  var qs = Object.keys(params).sort().map(function (k) { return k + "=" + encodeURIComponent(params[k]); }).join("&");
  var sign = native.md5(Object.keys(params).sort().map(function (k) { return k + "=" + params[k]; }).join("") + key);
  return "https://api-bc.wtzw.com/api/v5/category/get-list?" + qs + "&sign=" + sign;
}

