  return qmCmForm({
    book_id: ids.bid, chapter_id: ids.cid,
    paragraph_id: String(pid || ''),
    check_cmt_id: '', hot: String(hot || '0'), exposed_ids: '', need_common: '0'
  });
}

function qmCmChapterBody(chapterUrl, hot) {
  var ids = qmCmIds(chapterUrl);
  return qmCmForm({
    book_id: ids.bid, chapter_id: ids.cid, hot: String(hot || '0'),
    exposed_ids: '', need_common: '0', extra: ''
  });
}

function qmCmItems(resp) {
  var out = [];
  try {
    var d = (resp && resp.data) || {};
    var zones = ['hot_zone', 'time_zone'];
    for (var z = 0; z < zones.length; z++) {
      var list = (d[zones[z]] || {}).comment_list || [];
      for (var i = 0; i < list.length; i++) {
        if (list[i]) { out.push(list[i]); }
      }
    }
  } catch (e) {}
  return out;
}

function qmCmTotal(resp, fallback) {
  try {
    var d = (resp && resp.data) || {};
    var tz = d.time_zone || {}, hz = d.hot_zone || {};
    var n = Number(tz.comment_count || hz.comment_count || 0);
    if (n > 0) { return n; }
  } catch (e) {}
  return Number(fallback || 0);
}

function qmCmParaTitle(i) {
  return '第 ' + (Number(i) + 1) + ' 段段评';
}

/* ---------- 双流合并：hot=0(最新10) + hot=1(热门10)，去重后最多 20 条 ----------
 * 依据：/paragraph/first 与 /chapter-comment/first 都只返 10 条，
 *       但 hot 参数切换后返回完全不同的一批（实测重复 0）。
 *       页面 fetch 预算最多 3 个请求，故取 2 个刚好。
 */
function qmCmMerge(a, b) {
  var out = [], seen = {};
  var lists = [qmCmItems(a), qmCmItems(b)];
  for (var l = 0; l < lists.length; l++) {
    var arr = lists[l];
    for (var i = 0; i < arr.length; i++) {
      var x = arr[i] || {};
      var key = String(x.comment_id || x.content_id || (x.user_info || {}).uid + '|' + x.content);
      if (seen[key]) { continue; }
      seen[key] = 1;
      out.push(x);
    }
  }
  return out;
}

// 两路合计条数（用于标题显示"共 N 条"）
function qmCmMergeTotal(a, b, fallback) {
  var n = qmCmItems(a).length + qmCmItems(b).length;
  if (n > 0) { return n; }
  return qmCmTotal(a, fallback);
}
